import { test, expect, type Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/reg1-r12.json'), colorScheme: 'dark' });

const ownButton = (page: Page) => page.getByRole('button', { name: /הסטורי שלי/ });

// Открыть /discover при заданном окне и дождаться, что кнопка «הסטורי שלי» — верхний элемент в своём центре (ушёл сплэш).
async function openDiscoverAt(page: Page, width: number, height: number) {
  await page.setViewportSize({ width, height });
  await page.goto('/discover');
  const btn = ownButton(page);
  await expect(btn).toBeVisible();
  await expect
    .poll(() =>
      btn.evaluate((el) => {
        const r = el.getBoundingClientRect();
        const top = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
        return !!top && el.contains(top);
      }),
    )
    .toBe(true);
}

test.describe('Раунд 13: кружки сторис 62/60/57/52 (#c94032)', () => {
  test('Узкие экраны: 375→60, 360→57, 320→52, без горизонтальной прокрутки @iphone @prod-safe', async ({ page }) => {
    // 1. Для ширин 375, 360, 320: установить viewport, `/discover`, снять rect кружка «הסטורי שלי».
    for (const [width, expected] of [[375, 60], [360, 57], [320, 52]]) {
      await openDiscoverAt(page, width, 812);
      const own = ownButton(page).locator('div').first();
      await expect
        .poll(async () => Math.round((await own.boundingBox())!.width), { message: `кружок при ширине ${width}` })
        .toBe(expected);
      const box = (await own.boundingBox())!;
      expect(Math.abs(box.width - expected), `ширина при ${width}`).toBeLessThanOrEqual(1);
      expect(Math.abs(box.height - expected), `высота при ${width}`).toBeLessThanOrEqual(1);

      // 2. Снять `document.documentElement.scrollWidth`.
      const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
      expect(scrollWidth, `нет горизонтальной прокрутки при ${width}`).toBeLessThanOrEqual(width);

      // Кружок целиком в окне (x ≥ 0, правый край ≤ ширина).
      expect(box.x, `кружок слева в окне при ${width}`).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width, `кружок справа в окне при ${width}`).toBeLessThanOrEqual(width);
    }
  });
});
